import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import "./App.scss";
import LoginRegisterForm from "./components/LoginRegisterContainer/LoginRegisterContainer";
import AdminCustomerContainer from "./components/AdminCustomerContainer/AdminCustomerContainer";
import SellerContainer from "./components/SellerContainer/SellerContainer";
import ProfileUpdate from "./components/ProfileUpdate/ProfileUpdate";

function App() {
  // Récupérer l'utilisateur stocké dans sessionStorage
  const storedUser = JSON.parse(sessionStorage.getItem("user")) || {};
  const [isUserAuthenticated, setUserAuthorization] = useState(
    JSON.parse(sessionStorage.getItem("isUserAuthenticated")) || false
  );
  const [isAdmin, setAdmin] = useState(storedUser.isAdmin || 0); // Récupérer la vraie valeur de isAdmin
  const [customerId, setCustomerId] = useState(
    sessionStorage.getItem("customerId") || undefined
  );

  // Fonction pour définir l'état de l'utilisateur authentifié
  const setUserAuthenticatedStatus = (isAdmin, customerId) => {
    setUserAuthorization(true);
    setAdmin(isAdmin);
    setCustomerId(customerId);

    // Stocker les informations utilisateur complètes
    sessionStorage.setItem(
      "user",
      JSON.stringify({ userId: customerId, isAdmin: isAdmin })
    );
    sessionStorage.setItem("isUserAuthenticated", true);
    sessionStorage.setItem("customerId", customerId);
  };

  // Fonction pour gérer la déconnexion
  const handleLogout = () => {
    sessionStorage.removeItem("user");
    sessionStorage.removeItem("isUserAuthenticated");
    sessionStorage.removeItem("customerId");

    setUserAuthorization(false);
    setAdmin(0); // Réinitialise isAdmin à 0
    setCustomerId(undefined);
  };

  return (
    <Router>
      <Routes>
        {/* Route pour le formulaire de connexion/inscription */}
        <Route
          path="/"
          element={
            !isUserAuthenticated ? (
              <LoginRegisterForm setUserAuthenticatedStatus={setUserAuthenticatedStatus} />
            ) : (
              <>
                <div className="login-button-container">
                  <button
                    onClick={() => {
                      const userId = sessionStorage.getItem("customerId");
                      window.location.href = `/update-profile?userId=${userId}`;
                    }}
                    className="login-button"
                  >
                    Update Profile
                  </button>
                </div>
                <div className="login-button-container">
                  <button onClick={handleLogout} className="login-button">
                    Logout
                  </button>
                </div>
                {/* Vérification des rôles */}
                {(() => {
                  console.log("isAdmin value in App.js:", isAdmin); // Vérifiez la valeur réelle de isAdmin
                  if (isAdmin === 1) {
                    return <AdminCustomerContainer isAdmin={isAdmin} customerId={customerId} />;
                  } else if (isAdmin === 2) {
                    return <SellerContainer isAdmin={isAdmin} />;
                  } else {
                    return <div>You do not have the proper role to access this page.</div>;
                  }
                })()}
              </>
            )
          }
        />

        {/* Route pour la mise à jour du profil */}
        <Route path="/update-profile" element={<ProfileUpdate />} />
      </Routes>
    </Router>
  );
}

export default App;
